import React, { useState } from "react";
import styled from "styled-components";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from "firebase/auth";
import { doc, setDoc } from "firebase/firestore";
import { db } from "../services/firebaseConfig";
import { auth } from "../services/firebaseConfig";

const LoginPage = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [userType, setUserType] = useState("personal");
  const [error, setError] = useState("");
  const [isLogin, setIsLogin] = useState(true);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      await signInWithEmailAndPassword(auth, email, password);
      navigate("/dashboard");
    } catch (err) {
      setError("Credenciais inválidas ou conta inexistente 😕");
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;
      await setDoc(doc(db, 'users', user.uid), {
        email: user.email,
        userType: userType,
        createdAt: new Date(),
      });
      navigate("/dashboard");
    } catch (err) {
      setError("Erro ao criar conta. Tente novamente 😕");
    }
  };

  return (
    <Container>
      <Card
        as={motion.div}
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <Logo>💸 <span>CashPilot</span></Logo>
        <Title>{isLogin ? "Entrar" : "Criar Conta"}</Title>

        <Form onSubmit={isLogin ? handleLogin : handleRegister}>
          {!isLogin && (
            <>
              <Input type="text" placeholder="Nome completo" required />
              <UserTypeContainer>
                <RadioLabel>
                  <RadioInput
                    type="radio"
                    name="userType"
                    value="personal"
                    checked={userType === "personal"}
                    onChange={() => setUserType("personal")}
                  />
                  Pessoal
                </RadioLabel>
                <RadioLabel>
                  <RadioInput
                    type="radio"
                    name="userType"
                    value="business"
                    checked={userType === "business"}
                    onChange={() => setUserType("business")}
                  />
                  Empresa
                </RadioLabel>
              </UserTypeContainer>
            </>
          )}

          <InputGroup>
            <FieldLabel htmlFor="email">E-mail</FieldLabel>
            <Input
              id="email"
              type="email"
              placeholder="exemplo@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </InputGroup>

          <InputGroup>
            <FieldLabel htmlFor="password">Senha</FieldLabel>
            <Input
              id="password"
              type="password"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </InputGroup>

          {isLogin && (
            <CheckboxContainer>
              <CheckboxInput type="checkbox" id="remember" />
              <CheckboxLabel htmlFor="remember">Lembrar de mim</CheckboxLabel>
            </CheckboxContainer>
          )}

          {error && <ErrorMessage>{error}</ErrorMessage>}

          <Button type="submit">
            {isLogin ? "Entrar" : "Registrar"}
          </Button>
        </Form>

        <Switch>
          {isLogin ? (
            <>
              Não tem conta?{" "}
              <SwitchLink onClick={() => setIsLogin(false)}>Cadastre-se</SwitchLink>
              <br />
              <SwitchLinkSmall onClick={() => navigate("/reset")}>
                Esqueceu a senha?
              </SwitchLinkSmall>
            </>
          ) : (
            <>
              Já tem conta?{" "}
              <SwitchLink onClick={() => setIsLogin(true)}>Entre</SwitchLink>
            </>
          )}
        </Switch>
      </Card>
    </Container>
  );
};

export default LoginPage;

// ============= STYLES =============

const Container = styled.div`
  min-height: 100vh;
  width: 100%;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-md);
`;

const Card = styled.div`
  background: #1e293b;
  padding: var(--space-lg);
  border-radius: var(--radius-lg);
  box-shadow: 0 0 25px rgba(56, 189, 248, 0.2);
  width: 100%;
  max-width: 400px;
  text-align: center;
  color: #f1f5f9;
  border: 1px solid rgba(56, 189, 248, 0.2);

  @media (min-width: 480px) {
    padding: 2.5rem;
    border-radius: 16px;
  }
`;

const Logo = styled.div`
  font-size: clamp(1.5rem, 5vw, 2rem);
  font-weight: 700;
  color: #38bdf8;
  margin-bottom: var(--space-md);

  span {
    color: #f8fafc;
  }
`;

const Title = styled.h2`
  margin-bottom: var(--space-lg);
  color: #38bdf8;
  font-size: var(--fs-xl);
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
`;

const InputGroup = styled.div`
  text-align: left;
`;

const FieldLabel = styled.label`
  display: block;
  font-size: var(--fs-sm);
  color: #94a3b8;
  margin-bottom: var(--space-xs);
`;

const Input = styled.input`
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: var(--radius-md);
  padding: var(--space-sm) var(--space-md);
  color: #f8fafc;
  font-size: var(--fs-base);
  outline: none;
  transition: all 0.2s ease;
  width: 100%;
  min-height: 48px;

  &:focus {
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
  }

  &::placeholder {
    color: #64748b;
  }
`;

const CheckboxContainer = styled.div`
  display: flex;
  align-items: center;
  justify-content: flex-start;
  font-size: var(--fs-sm);
  color: #94a3b8;
`;

const CheckboxInput = styled.input`
  accent-color: #38bdf8;
  margin-right: var(--space-sm);
  width: 18px;
  height: 18px;
  min-width: 18px;
  cursor: pointer;
`;

const CheckboxLabel = styled.label`
  cursor: pointer;
  user-select: none;
`;

const RadioInput = styled.input`
  accent-color: #38bdf8;
  margin-right: var(--space-xs);
  width: 16px;
  height: 16px;
  cursor: pointer;
`;

const UserTypeContainer = styled.div`
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  margin-top: var(--space-xs);
  font-size: var(--fs-sm);
  color: #94a3b8;

  @media (max-width: 479px) {
    gap: var(--space-sm);
  }
`;

const RadioLabel = styled.label`
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  background: #0b1220;
  padding: var(--space-sm);
  border-radius: var(--radius-md);
  border: 1px solid #273449;
  cursor: pointer;
  transition: all 0.15s;
  font-size: var(--fs-xs);

  &:hover {
    transform: translateY(-2px);
    border-color: #38bdf8;
    color: #e6f9ff;
  }

  input[type="radio"] {
    accent-color: #38bdf8;
  }

  @media (min-width: 480px) {
    padding: var(--space-sm) var(--space-md);
    font-size: var(--fs-sm);
    
    input[type="radio"] {
      width: 16px;
      height: 16px;
    }
  }
`;

const ErrorMessage = styled.p`
  color: #ef4444;
  font-size: var(--fs-sm);
  text-align: center;
  padding: var(--space-sm);
  background: rgba(239, 68, 68, 0.1);
  border-radius: var(--radius-md);
`;

const Button = styled.button`
  background: #38bdf8;
  border: none;
  color: #0f172a;
  font-weight: 600;
  padding: var(--space-md);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.3s;
  font-size: var(--fs-base);
  min-height: 48px;
  margin-top: var(--space-sm);

  &:hover {
    background: #0ea5e9;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(56, 189, 248, 0.4);
  }

  &:active {
    transform: scale(0.98);
  }
`;

const Switch = styled.p`
  margin-top: var(--space-lg);
  font-size: var(--fs-sm);
  color: #94a3b8;
  line-height: 1.6;
`;

const SwitchLink = styled.span`
  color: #38bdf8;
  cursor: pointer;
  font-weight: 600;
  
  &:hover {
    text-decoration: underline;
  }
`;

const SwitchLinkSmall = styled.span`
  color: #38bdf8;
  font-size: var(--fs-sm);
  cursor: pointer;
  
  &:hover {
    text-decoration: underline;
  }
`;

